pragma solidity ^0.8.20;

/**
 * @title NGODonation
 * @author Expert Solidity Engineer
 * @notice A contract for managing donation campaigns for non-governmental organizations (NGOs).
 * This contract allows a designated owner to create and manage fundraising campaigns.
 * Donors can contribute Ether (ETH) to active campaigns.
 * Beneficiaries of each campaign can withdraw the funds raised for them.
 * The contract includes basic security patterns like Ownable, Pausable, and ReentrancyGuard,
 * implemented inline to avoid external dependencies.
 */
contract NGODonation {
    // =============================================================
    // Inline Patterns (Ownable, Pausable, ReentrancyGuard)
    // =============================================================

    // --- Ownable ---
    address private _owner;
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    modifier onlyOwner() {
        require(owner() == msg.sender, "Ownable: caller is not the owner");
        _;
    }

    function owner() public view returns (address) {
        return _owner;
    }

    function transferOwnership(address newOwner) public virtual onlyOwner {
        require(newOwner != address(0), "Ownable: new owner is the zero address");
        address oldOwner = _owner;
        _owner = newOwner;
        emit OwnershipTransferred(oldOwner, newOwner);
    }

    // --- Pausable ---
    bool private _paused;
    event Paused(address account);
    event Unpaused(address account);

    modifier whenNotPaused() {
        require(!paused(), "Pausable: paused");
        _;
    }

    modifier whenPaused() {
        require(paused(), "Pausable: not paused");
        _;
    }

    function paused() public view returns (bool) {
        return _paused;
    }

    function pause() public onlyOwner whenNotPaused {
        _paused = true;
        emit Paused(msg.sender);
    }

    function unpause() public onlyOwner whenPaused {
        _paused = false;
        emit Unpaused(msg.sender);
    }

    // --- ReentrancyGuard ---
    uint256 private _status;
    uint256 private constant _NOT_ENTERED = 1;
    uint256 private constant _ENTERED = 2;

    modifier nonReentrant() {
        require(_status != _ENTERED, "ReentrancyGuard: reentrant call");
        _status = _ENTERED;
        _;
        _status = _NOT_ENTERED;
    }

    // =============================================================
    // Contract State
    // =============================================================

    struct Campaign {
        string name;
        string metadataURI;
        address payable beneficiary;
        uint256 goal;
        uint256 raisedAmount;
        uint256 withdrawnAmount;
        bool active;
    }

    uint256 private _campaignIdCounter;
    mapping(uint256 => Campaign) private _campaigns;
    mapping(uint256 => mapping(address => uint256)) private _donations;

    // =============================================================
    // Events
    // =============================================================

    event CampaignCreated(uint256 indexed campaignId, address indexed beneficiary, uint256 goal, string name);
    event DonationReceived(uint256 indexed campaignId, address indexed donor, uint256 amount, string message);
    event FundsWithdrawn(uint256 indexed campaignId, address indexed beneficiary, uint256 amount);
    event CampaignClosed(uint256 indexed campaignId);

    // =============================================================
    // Constructor
    // =============================================================

    constructor() {
        _owner = msg.sender;
        emit OwnershipTransferred(address(0), msg.sender);
        _status = _NOT_ENTERED;
    }

    // =============================================================
    // External Functions
    // =============================================================

    /**
     * @notice Creates a new donation campaign. Only the contract owner can call this.
     * @param name The name of the campaign.
     * @param metadataURI A URI pointing to more details about the campaign (e.g., IPFS).
     * @param beneficiary The address that will receive the donated funds.
     * @param goal The fundraising goal in wei.
     * @return The ID of the newly created campaign.
     */
    function createCampaign(
        string calldata name,
        string calldata metadataURI,
        address payable beneficiary,
        uint256 goal
    ) external onlyOwner returns (uint256) {
        require(beneficiary != address(0), "NGODonation: Beneficiary cannot be zero address");
        require(goal > 0, "NGODonation: Goal must be greater than zero");

        uint256 campaignId = ++_campaignIdCounter;
        _campaigns[campaignId] = Campaign({
            name: name,
            metadataURI: metadataURI,
            beneficiary: beneficiary,
            goal: goal,
            raisedAmount: 0,
            withdrawnAmount: 0,
            active: true
        });

        emit CampaignCreated(campaignId, beneficiary, goal, name);
        return campaignId;
    }

    /**
     * @notice Donates ETH to a specific campaign.
     * @param campaignId The ID of the campaign to donate to.
     * @param message A message from the donor.
     */
    function donate(uint256 campaignId, string calldata message) external payable whenNotPaused nonReentrant {
        require(msg.value > 0, "NGODonation: Donation amount must be positive");
        Campaign storage campaign = _campaigns[campaignId];
        require(campaign.beneficiary != address(0), "NGODonation: Campaign does not exist");
        require(campaign.active, "NGODonation: Campaign is not active");

        campaign.raisedAmount += msg.value;
        _donations[campaignId][msg.sender] += msg.value;

        emit DonationReceived(campaignId, msg.sender, msg.value, message);
    }

    /**
     * @notice Allows a campaign's beneficiary to withdraw funds.
     * @param campaignId The ID of the campaign to withdraw from.
     * @param amount The amount of ETH to withdraw in wei.
     */
    function withdraw(uint256 campaignId, uint256 amount) external nonReentrant {
        require(amount > 0, "NGODonation: Withdraw amount must be positive");
        Campaign storage campaign = _campaigns[campaignId];

        require(campaign.beneficiary != address(0), "NGODonation: Campaign does not exist");
        require(msg.sender == campaign.beneficiary, "NGODonation: Only the beneficiary can withdraw");

        uint256 availableToWithdraw = campaign.raisedAmount - campaign.withdrawnAmount;
        require(amount <= availableToWithdraw, "NGODonation: Insufficient funds in campaign for this amount");

        // Checks-Effects-Interactions pattern
        campaign.withdrawnAmount += amount;

        // solhint-disable-next-line avoid-low-level-calls
        (bool success, ) = campaign.beneficiary.call{value: amount}("");
        require(success, "NGODonation: ETH transfer failed");

        emit FundsWithdrawn(campaignId, campaign.beneficiary, amount);
    }

    /**
     * @notice Closes a campaign, preventing further donations. Can be called by the owner or the beneficiary.
     * @param campaignId The ID of the campaign to close.
     */
    function closeCampaign(uint256 campaignId) external {
        Campaign storage campaign = _campaigns[campaignId];
        require(campaign.beneficiary != address(0), "NGODonation: Campaign does not exist");
        require(
            msg.sender == owner() || msg.sender == campaign.beneficiary,
            "NGODonation: Not authorized to close campaign"
        );
        require(campaign.active, "NGODonation: Campaign is already closed");

        campaign.active = false;
        emit CampaignClosed(campaignId);
    }

    // =============================================================
    // View Functions
    // =============================================================

    /**
     * @notice Retrieves details for a specific campaign.
     * @param campaignId The ID of the campaign.
     * @return name The name of the campaign.
     * @return metadataURI The URI for the campaign's metadata.
     * @return beneficiary The address of the campaign beneficiary.
     * @return goal The campaign's fundraising goal.
     * @return raisedAmount The total amount raised by the campaign.
     * @return withdrawnAmount The total amount withdrawn from the campaign.
     * @return active The current status of the campaign (active or closed).
     */
    function getCampaign(uint256 campaignId)
        external
        view
        returns (
            string memory name,
            string memory metadataURI,
            address payable beneficiary,
            uint256 goal,
            uint256 raisedAmount,
            uint256 withdrawnAmount,
            bool active
        )
    {
        Campaign storage c = _campaigns[campaignId];
        require(c.beneficiary != address(0), "NGODonation: Campaign does not exist");
        return (c.name, c.metadataURI, c.beneficiary, c.goal, c.raisedAmount, c.withdrawnAmount, c.active);
    }

    /**
     * @notice Returns the total number of campaigns created.
     */
    function campaignCount() external view returns (uint256) {
        return _campaignIdCounter;
    }

    /**
     * @notice Returns the total amount a specific donor has contributed to a campaign.
     * @param campaignId The ID of the campaign.
     * @param donor The address of the donor.
     */
    function donorTotal(uint256 campaignId, address donor) external view returns (uint256) {
        return _donations[campaignId][donor];
    }

    /**
     * @notice Returns the total amount raised for a specific campaign.
     * @param campaignId The ID of the campaign.
     */
    function campaignRaised(uint256 campaignId) external view returns (uint256) {
        return _campaigns[campaignId].raisedAmount;
    }
}

